#include "source_coupling.h"
#include "source_coupling_math.h"
#include "longitudinal_shape.h"
#include "eb_mpi.h"
#include "runtime_util.h"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>

using namespace aprl;
using Vec=FieldVector<Double>;
namespace {
void require(bool value,const char* text){if(!value)throw std::runtime_error(text);}
bool same(Double a,Double b){return std::memcmp(&a,&b,sizeof(a))==0;}
void equal(const RelativisticParticleSI& a,const RelativisticParticleSI& b){for(unsigned d=0;d<3;++d)require(same(a.position[d],b.position[d])&&same(a.properVelocity[d],b.properVelocity[d]),"One-way trajectory differs from prescribed-only EC trajectory");}
void fill(EBFieldGrid& f,std::size_t offset,double phase){YeeComponent* v[6]={&f.ex(),&f.ey(),&f.ez(),&f.bx(),&f.by(),&f.bz()};for(unsigned a=0;a<6;++a)for(std::size_t k=0;k<v[a]->nz();++k)for(std::size_t j=0;j<v[a]->ny();++j)for(std::size_t i=0;i<v[a]->nx();++i)(*v[a])(i,j,k)=(a<3?1e8:.3)*std::sin(.13*i+.19*j+.23*(k+offset)+a+phase);}
RelativisticParticleSI prescribed(RelativisticParticleSI p,const SIFieldSourceSet& sources,const BoostFrameTransform& frame,double time,double dt,unsigned steps){const double h=dt/steps;for(unsigned n=0;n<steps;++n){const auto before=p;const double g0=BoostFrameTransform::gammaFromProperVelocity(p.properVelocity);Vec point(p.position);point.pmv(.5*h*SI::c/g0,p.properVelocity);Vec e(0.),b(0.);sources.addPrescribedBox(point,time+(n+.5)*h,frame,e,b);source_coupling_math::momentum(p.properVelocity,e,b,p.charge,p.mass,h,g0);const double g1=BoostFrameTransform::gammaFromProperVelocity(p.properVelocity);Vec mean(before.properVelocity);mean+=p.properVelocity;p.position.pmv(h*SI::c/(g0+g1),mean);}return p;}
long double meshWork(const EBFieldGrid& f,const source_coupling_math::Electric& old,int rank,int size){long double work=0.;const YeeComponent* e[3]={&f.ex(),&f.ey(),&f.ez()},*j[3]={&f.jx(),&f.jy(),&f.jz()};const auto& g=f.geometry();for(unsigned d=0;d<3;++d)for(std::size_t k=0;k<j[d]->nz();++k)for(std::size_t y=0;y<j[d]->ny();++y)for(std::size_t x=0;x<j[d]->nx();++x){long double weight=1.;if(d<2&&((rank>0&&k==0)||(rank+1<size&&k==g.nz)))weight=.5;work+=weight*.5L*((long double)old[d](x,y,k)+(*e[d])(x,y,k))*(*j[d])(x,y,k);}return work*(long double)g.dt*g.dx*g.dy*g.dz;}
long double readPassive(const std::string& directory,int rank){std::ostringstream name;name<<directory<<"/one-way-source-rank-"<<std::setw(5)<<std::setfill('0')<<rank<<".csv";std::ifstream input(name.str());std::string header,line;require(bool(std::getline(input,header))&&bool(std::getline(input,line)),"Missing one-way work row");std::replace(line.begin(),line.end(),',',' ');std::istringstream row(line);std::size_t step,count;long double passive,controller,absolute,x,y,z;require(bool(row>>step>>passive>>controller>>absolute>>x>>y>>z>>count),"Malformed one-way work row");require(step==1&&count==1,"One-way work row has wrong step or segment count");require(controller==-passive,"Controller work is not minus passive work");require(std::abs(passive-x-y-z)<1e-18L*std::max(absolute,1e-100L),"Passive components do not sum to total");require(absolute>=std::abs(passive),"Passive absolute work is below signed work");require(!std::getline(input,line),"Duplicate one-way work row");return passive;}
}
int main(int argc,char** argv){MPI_Init(&argc,&argv);int rank=0,size=1;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&size);try{require(argc==2,"Need independent output directory");const std::string root=argv[1];const double dz=1.2543262415359034e-6;const EBGridGeometry g(12,14,16,5e-6,5e-6,dz,dz/SI::c,EBMaxwellSolver::CowanZ);Vec origin(0.);origin[2]=rank*g.nz*dz;BoostFrameTransform frame;frame.setFromGamma(2.,SI::c,0.);double maximumWorkError=0.,minimumSourceChange=1e300,minimumFeedbackChange=1e300;
 for(bool device:{false,true}){
  const std::string directory=root+(device?"/with-device":"/free");createDirectories(directory,MPI_COMM_WORLD);EBFieldGrid f(g);fill(f,rank*g.nz,0.);const auto old=source_coupling_math::copyElectric(f);
  RelativisticParticleSI initial;initial.id=initial.sourceId=rank+1;initial.charge=-SI::elementaryCharge;initial.mass=SI::electronMass;initial.weight=1.;initial.position=origin;initial.position[0]+=4.2*g.dx;initial.position[1]+=5.3*g.dy;initial.position[2]+=7.25*dz;initial.properVelocity=Vec(0.);initial.properVelocity[0]=.19;initial.properVelocity[1]=-.07;initial.properVelocity[2]=.61;
  SIFieldSourceSet sources;if(device){SIMagneticElement magnet;magnet.type=SIMagnetType::UniformDipole;magnet.center=Vec(0.);magnet.length=1.;magnet.peakMagneticField=.2;magnet.polarizationAngle=.37;magnet.prepare();sources.addPrescribedLabMagnet(magnet);}
  const auto oracle=prescribed(initial,sources,frame,0.,g.dt,7);
  // A second, deliberately different nonzero grid must have no influence on
  // prescribed trajectories or on the deposited source. This is a negative
  // control for accidentally retaining a grid-field gather in the pusher.
  const std::string otherDirectory=directory+"/different-grid";createDirectories(otherDirectory,MPI_COMM_WORLD);EBFieldGrid other(g);fill(other,rank*g.nz,2.17);ConservativeSourceCoupling otherCoupling(MPI_COMM_WORLD,otherDirectory,false,false,true,true,true);otherCoupling.begin(other,origin,{initial});otherCoupling.beginTrial();otherCoupling.exchangeCandidate();auto otherParticle=initial;otherCoupling.push(otherParticle,sources,frame,0.,g.dt,7,nullptr,nullptr,nullptr);equal(otherParticle,oracle);otherCoupling.close(0);
  ConservativeSourceCoupling coupling(MPI_COMM_WORLD,directory,false,false,true,true,true);coupling.begin(f,origin,{initial});fill(f,rank*g.nz,.41);coupling.beginTrial();coupling.exchangeCandidate();auto p=initial;coupling.push(p,sources,frame,0.,g.dt,7,nullptr,nullptr,nullptr);equal(p,oracle);
  const auto r=coupling.localResidual();require(r[0]==0.&&r[1]==0.&&r[2]==0.&&r[3]==1.,"One-way residual requests self-field convergence");
  ChargeConservingCurrentDepositor depositor(f,origin,coupling.longitudinalCurrent());depositor.depositSegment(initial.position,p.position,p.charge);coupling.completeCurrent();EBZSlabHaloExchange halo(MPI_COMM_WORLD);halo.sumSharedTangentialCurrent(f);const auto wave=source_coupling_math::copyElectric(f);coupling.applyCurrentSource(-1.);double changed=0.;for(unsigned a=0;a<3;++a){const auto& e=a==0?f.ex():(a==1?f.ey():f.ez());for(std::size_t i=0;i<e.size();++i)changed=std::max(changed,std::abs(e.data()[i]-wave[a].data()[i]));}require(changed>0.,"One-way current did not drive Maxwell source");minimumSourceChange=std::min(minimumSourceChange,changed);
  coupling.applyCurrentSource(1.);f.clearCurrent();coupling.swapElectric();coupling.setReplay(true);p=initial;BorisWork work;coupling.push(p,sources,frame,0.,g.dt,7,nullptr,&work,nullptr);equal(p,oracle);require(work.gridWork==0.,"One-way trajectory received actual grid work");require(std::abs(work.totalDeltaK-work.prescribedWork-work.roundoffResidual)<1e-30L,"One-way pusher work decomposition failed");
  depositor.depositSegment(initial.position,p.position,p.charge);coupling.recordActiveSegment(initial.position,p.position,p.charge);coupling.completeCurrent();coupling.setReplay(false);coupling.finish(1,1,0.,0.);coupling.swapElectric();halo.sumSharedTangentialCurrent(f);coupling.applyCurrentSource(-1.);const long double independent=meshWork(f,old,rank,size);coupling.finalizeConstraints();coupling.close(1);const long double passive=readPassive(directory,rank);
  require(std::abs(passive)>0.,"Passive self-field diagnostic was silently zeroed");const long double local[2]={passive,independent};long double global[2]={};MPI_Allreduce(local,global,2,MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);const double error=double(std::abs(global[0]-global[1])/std::max(std::abs(global[1]),1e-100L));maximumWorkError=std::max(maximumWorkError,error);require(error<2e-12,"Passive one-way work differs from native F3 mesh work");
  const std::string fullDirectory=directory+"/feedback-control";createDirectories(fullDirectory,MPI_COMM_WORLD);EBFieldGrid full(g);fill(full,rank*g.nz,0.);ConservativeSourceCoupling feedback(MPI_COMM_WORLD,fullDirectory,false,false,true,true);feedback.begin(full,origin,{initial});feedback.exchangeCandidate();auto self=initial;feedback.push(self,sources,frame,0.,g.dt,7,nullptr,nullptr,nullptr);double difference=0.;for(unsigned a=0;a<3;++a)difference=std::max(difference,std::abs(self.properVelocity[a]-oracle.properVelocity[a]));require(difference>1e-8,"Full-feedback negative control did not respond to strong self fields");minimumFeedbackChange=std::min(minimumFeedbackChange,difference);feedback.close(0);
 }
 if(rank==0)std::cout<<std::setprecision(18)<<"{\"passed\":true,\"physical_acceptance\":false,\"ranks\":"<<size<<",\"prescribed_only_ec_bitwise\":true,\"actual_grid_work_zero\":true,\"max_passive_mesh_work_relative_error\":"<<maximumWorkError<<",\"minimum_source_electric_change\":"<<minimumSourceChange<<",\"minimum_feedback_negative_control_delta_u\":"<<minimumFeedbackChange<<"}\n";
 }catch(const std::exception& error){std::cerr<<error.what()<<'\n';MPI_Abort(MPI_COMM_WORLD,1);}MPI_Finalize();return 0;}
